    """Intersect the two equal-sized nonzero masks around a solid divider."""
    h, w = len(grid), len(grid[0])
    cuts = []
    for r, row in enumerate(grid):
        if row[0] != 0 and all(v == row[0] for v in row):
            a, b = grid[:r], grid[r + 1:]
            if len(a) == len(b) and a and all(len(x) == len(y) == w for x, y in zip(a, b)):
                cuts.append((a, b))
    for c in range(w):
        v = grid[0][c]
        if v != 0 and all(row[c] == v for row in grid):
            a = [row[:c] for row in grid]
            b = [row[c + 1:] for row in grid]
            if c == w - c - 1 and c > 0:
                cuts.append((a, b))
    if len(cuts) != 1:
        raise ValueError(f"expected one equal-sized pair around a solid divider, found {len(cuts)}")
